/**
 * MetaLocator all.min.js
 *
 * Aggregated and minified production bundle.
 * Source: directory-tabs.js (and other component scripts).
 *
 * This file includes the setupDirectoryTabs() initialisation logic that
 * normalises Bootstrap tab markup at runtime.
 */

/* --- directory-tabs --------------------------------------------------- */
(function(){"use strict";function setupDirectoryTabs(){var t=document.querySelectorAll(".tab-content");t.forEach(function(c){if(c.querySelectorAll(".tab-content").length>0){console.warn("MetaLocator: Duplicate tab-content containers detected. Check tab templates.")}});var n=document.querySelectorAll(".nav-tabs");n.forEach(function(nav){var links=nav.querySelectorAll(".nav-link");if(links.length===0)return;var paneIds=[];links.forEach(function(l){var h=l.getAttribute("href");if(h&&h.charAt(0)==="#")paneIds.push(h.substring(1))});var tabContent=null,sib=nav.nextElementSibling;while(sib){if(sib.classList&&sib.classList.contains("tab-content")){tabContent=sib;break}sib=sib.nextElementSibling}if(!tabContent&&paneIds.length>0){var fp=document.getElementById(paneIds[0]);if(fp)tabContent=fp.parentElement}if(!tabContent)return;links.forEach(function(l){var h=l.getAttribute("href");if(h&&h.charAt(0)==="#"){var pid=h.substring(1);l.setAttribute("aria-controls",pid);if(!document.getElementById(pid)){console.warn('MetaLocator: nav-link references pane "'+pid+'" which does not exist in the DOM.')}}});paneIds.forEach(function(pid){var p=document.getElementById(pid);if(p)p.setAttribute("aria-labelledby",pid+"-tab")});links.forEach(function(l){l.classList.remove("active");l.setAttribute("aria-selected","false")});var panes=tabContent.querySelectorAll(".tab-pane");panes.forEach(function(p){p.classList.remove("active","show");if(!p.classList.contains("fade"))p.classList.add("fade")});var fl=links[0];fl.classList.add("active");fl.setAttribute("aria-selected","true");if(paneIds.length>0){var fpe=document.getElementById(paneIds[0]);if(fpe)fpe.classList.add("active","show")}})}window.setupDirectoryTabs=setupDirectoryTabs;if(document.readyState==="loading"){document.addEventListener("DOMContentLoaded",setupDirectoryTabs)}else{setupDirectoryTabs()}})();
